INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 5214076, 0.5, 11, 1, "え、えっと……\nこれ、夢じゃないですよね？\nほっぺをつねっても……いひゃい！\nやっぱり夢じゃないれす！", 5214, 0, 105511, 10, 0);
