INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 13114067, 0.5, 11, 1, "イノリちゃんは彼が準備してるのを\nつまみ食いしながら\n見てただけじゃなかったっけ？", 13114, 0, 106711, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 13114068, "", 91, "", "", 13114, "", 0, "", "");
