INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 16114073, 0.5, 11, 1, "妹も！　妹もいましたからね！\nお姉ちゃん！", 16114, 0, 101111, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 16114074, "", 91, "", "", 16114, "", 0, "", "");
