INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 16614068, 0.5, 11, 1, "誕生、日……？\n私のですか？\nなぜそんなことを\n覚えているのですか？", 16614, 0, 102711, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 16614069, "", 91, "", "", 16614, "", 0, "", "");
