INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 16614076, "", 3, "", "wac_birthday_talk_normal", 16614, "", 102711, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, 16614077, "", 21, "", "vo_wac_16614_002", 16614, "", "vo_wac_16614", 0, "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 16614078, 0.5, 11, 1, "………………そう、ですか。\nそれならありがたく\nいただくことにしましょう。", 16614, 0, 102711, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 16614079, "", 91, "", "", 16614, "", 0, "", "");
