INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 17614080, 0.5, 11, 1, "本当に、いつもお疲れさまさ～♪\nおいしーケーキをたっくさん食べて、\nこれからも私たちの分まで、\nお仕事頑張ってね～？", 17614, 0, 101711, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 17614081, "", 91, "", "", 17614, "", 0, "", "");
