INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 18114058, 0.5, 11, 1, "私のために、ケーキで\nお祝いしてくれるなんて……\nみんなの先生でいられて、\n本当によかったって思うわ♪", 18114, 0, 101811, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 18114059, "", 91, "", "", 18114, "", 0, "", "");
