INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 18114068, 0.5, 11, 1, "ヒデサイにも買い出しとか\n手伝ってもらったしー\nみんなでお祝いする誕生日って、\nそれだけでエモいっしょ♪", 18114, 0, 101611, 10, 0);
