INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 19214058, 0.5, 11, 1, "わあー、これって私の\n誕生日ケーキですか？\nとってもおいしそう！", 19214, 0, 101111, 10, 0);
