INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 19414068, 0.5, 11, 1, "ちゃんと、私たちの気持ちが\n伝わるような贈り物にしたかったんだ。\nだから、味の方はあまり期待しないで\nくれるかな？", 19414, 0, 100311, 10, 0);
