INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 19814086, 0.5, 11, 1, "誕生日にそんなことされて喜ぶのは、\nクウカさんだけだと思います……", 19814, 0, 105511, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 19814087, "", 91, "", "", 19814, "", 0, "", "");
