INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 20014085, 0.5, 11, 1, "そっか……えへへ……♪\nなら、最初っからそう言いなさいよ。\nそしたら素直にお礼だって言えるし。\n……うん、ありがとう♪", 20014, 0, 106011, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 20014086, "", 91, "", "", 20014, "", 0, "", "");
