INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 20014095, 0.5, 11, 1, "撤回！　さっきのお礼はぜ～んぶ撤回！\nなんでまた魔物料理なわけ！？\nあんたたち、年に一度の誕生日くらい\nまともなもん食べさせなさいよ～！！", 20014, 0, 106011, 10, 0);
