INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 21014048, 0.5, 11, 1, "これは……私の誕生日ケーキですか？\nえっと、いったいどなたが……", 21014, 0, 118511, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 21014049, "", 91, "", "", 21014, "", 0, "", "");
