INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 21014053, 0.5, 11, 1, "【ギルド管理協会】に所属している\nギルドのみなさんと用意しました！\nいつもお世話になってますからね。\nお誕生日、おめでとうございます♪", 21014, 0, 105811, 10, 0);
