INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 22714061, 0.5, 11, 1, "……イノリちゃん？\nみんなイノリちゃんのためにケーキを\n用意して集まってくれてるんだから、\nまずはなんて言うのが正しいのかな～？", 22714, 0, 106711, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 22714062, "", 91, "", "", 22714, "", 0, "", "");
