INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 23214068, 0.5, 11, 1, "お誕生日おめでとう、ママ・サレン♪\nいつも、私たちのために、\n一生懸命お仕事頑張って\nくれてるから……", 23214, 0, 102111, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 23214069, "", 91, "", "", 23214, "", 0, "", "");
