INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 23214073, 0.5, 11, 1, "頑張って手作りしたんだよ？\nできあがる頃には、いろんな意味で\nスズメはボロボロになってたけど。", 23214, 0, 102311, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 23214074, "", 91, "", "", 23214, "", 23214073, "", "");
