INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 23814099, 0.5, 11, 1, "そうだったんだ……感謝しなきゃね♪\nお礼に今日は、好きな角度から\n心ゆくまで、ボクのかわいい顔を\n堪能してもらってかまわないよ♪", 23814, 0, 100811, 10, 0);
