INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 25314080, 0.5, 11, 1, "……その段取りを実行に移すために、\nボロ雑巾になるまで働いたのは\n自分たちなんスけど。", 25314, 0, 100511, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 25314081, "", 91, "", "", 25314, "", 0, "", "");
