INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, 32114084, "", 21, "", "vo_wac_32114_004", 32114, "", "vo_wac_32114", 0, "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 32114085, 0.5, 11, 1, "ほ、本当だべか！？\n苦労して誕生日パーティーを用意した\n甲斐があったべさ～……って、ん？\nちょっと待つべ、来年？", 32114, 0, 103311, 10, 0);
