INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 32314058, 0.5, 11, 1, "誕生日のお祝い、ありがとね！\nアタシももう、立派なレディの\n仲間入りって感じかしら♪", 32314, 0, 105011, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314059, "", 91, "", "", 32314, "", 0, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314060, "", 3, "", "wac_birthday_idle_smile", 32314, "", 105011, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314061, "", 3, "", "wac_birthday_talk_kyapi", 32314, "", 101611, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, 32314062, "", 21, "", "vo_wac_32314_001", 32314, "", "vo_wac_32314", 0, "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 32314063, 0.5, 11, 1, "ミサキっち、ホントおめでと～！\nとりま、飲み物はコーヒーでよさげ？\nお店で大人っぽい味でよろ～って\n頼んだら、おに苦くされたけど！", 32314, 0, 101611, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314064, "", 91, "", "", 32314, "", 0, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314065, "", 3, "", "wac_birthday_idle_kyapi", 32314, "", 101611, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314066, "", 3, "", "wac_birthday_talk_sad", 32314, "", 105011, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, 32314067, "", 21, "", "vo_wac_32314_002", 32314, "", "vo_wac_32314", 0, "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 32314068, 0.5, 11, 1, "えっ！？\nそ、それは、その～……\n大人のレディ向けジュースとかないの？\n苦いのも、別にダメじゃないけど！", 32314, 0, 105011, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314069, "", 91, "", "", 32314, "", 0, "", "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314070, "", 3, "", "wac_birthday_idle_sad", 32314, "", 105011, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314071, "", 3, "", "wac_birthday_talk_smile", 32314, "", 101811, 1, 0.2);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, 32314072, "", 21, "", "vo_wac_32314_003", 32314, "", "vo_wac_32314", 0, "");
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 32314073, 0.5, 11, 1, "ふふっ、ちゃんとあるわよ♪\nこうやってオシャレなグラスに\nぶどうジュースを注げば……\nほら、大人っぽいでしょう？", 32314, 0, 101811, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 32314074, "", 91, "", "", 32314, "", 0, "", "");
