INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 32314078, 0.5, 11, 1, "ほんとだ、なんかそれっぽい！\nえへへ、写真とか撮っちゃおうかな～♪\nアンタも一緒に入る？", 32314, 0, 105011, 10, 0);
