INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 33214068, 0.5, 11, 1, "顔を真っ赤にしてるレイさんなんて\nなかなか見られないからね～\nほらほら、騎士くんもしっかり\n目に焼き付けておきなよ♪", 33214, 0, 100111, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 33214069, "", 91, "", "", 33214, "", 0, "", "");
