INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 33214073, 0.5, 11, 1, "や、やめないかヒヨリ……！\nキミも真に受けて、じろじろ\n見るのはよしてくれ！\nますます変な顔になってしまう……！", 33214, 0, 100311, 10, 0);
