INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 36914085, 0.5, 11, 1, "ん？　何か特別な日だっただろうか？\n確かこの日がいいと言ったのは……\nキミだったか？", 36914, 0, 100311, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 36914086, "", 91, "", "", 36914, "", 0, "", "");
