INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 38014076, "", 3, "", "wac_birthday_talk_sad", 38014, "", 104611, 1, 0.2);
