INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 38614100, 0.5, 11, 1, "クスクス……安心してください。\n少なくともロウソクの数よりは、\nずっと若々しく見えていますわ……♪", 38614, 0, 102711, 10, 0);
