INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 38914048, 0.5, 11, 1, "素敵なケーキをありがとう！\n二人とも、私の誕生日、\n覚えててくれたんだ♪", 38914, 0, 105711, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 38914049, "", 91, "", "", 38914, "", 0, "", "");
