INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 39114078, 0.5, 11, 1, "麦しゅわの助けも借りながら、\nみんなで協力して、\n全部乗り越えることができたもの！", 39114, 0, 103411, 10, 0);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", 39114079, "", 91, "", "", 39114, "", 0, "", "");
