INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 39314063, 0.5, 11, 1, "誕生日のお祝い、ありがと～♪\nこんなふうに毎年、みんなでケーキを\n食べられてうれしいわ♪", 39314, 0, 105211, 10, 0);
