INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 39514063, 0.5, 11, 1, "うぅ……ぐすっ……ありがと～！！\nお誕生日を、こんなに、盛大に\nお祝いしてくれるなんて～！！", 39514, 0, 103411, 10, 0);
