INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 40314048, 0.5, 11, 1, "誕生日祝い、感謝いたします。\nまさか、貴方とリマさんからケーキを\nいただけるとは思いませんでしたが。", 40314, 0, 107011, 10, 0);
