INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 40314053, 0.5, 11, 1, "ネネカちゃんは、\n私の夢を叶えてくれた恩人ですもの。\nこれくらい、当然だわ♪\n彼も彼でお礼がしたかったみだいだし。", 40314, 0, 105211, 10, 0);
